---
/**
 * Admin Ops console — shared types (pure, importable from the web app, the
 * worker and tests alike; no I/O, no "use server").
 *
 * Every remote/long admin operation runs as ONE `Job` row of type ADMIN_OPS
 * whose `payload.op` discriminates what to do (see worker/admin-ops.ts). The
 * web side only ever enqueues + polls; the worker (root, the only process
 * allowed to touch iptables/Proxmox mutations) executes and writes the result
 * back into `payload.result`.
 */

export const ADMIN_OP_KINDS = [
  "diagnose",
  "guest_cmd",
  "ip_reassign",
  "ip_release",
  "ip_assign",
  "drift_scan",
  "orphan_vm_destroy",
  "orphan_ip_release",
  "bulk_power",
  // Placeholder RUNNING row on the OTHER server of a two-server op (IP
  // reassign) so that server's own power/config actions are refused until the
  // op finishes. Never claimed by the scheduler (it is created RUNNING); if a
  // worker restart re-queues it, the handler just completes it.
  "hold",
] as const;
export type AdminOpKind = (typeof ADMIN_OP_KINDS)[number];

export function isAdminOpKind(v: unknown): v is AdminOpKind {
  return typeof v === "string" && (ADMIN_OP_KINDS as readonly string[]).includes(v);
}

/** Ops that only READ — safe to run while the server has another job in flight. */
export const READ_ONLY_OPS: ReadonlySet<AdminOpKind> = new Set(["diagnose", "guest_cmd", "drift_scan"]);

/** Common envelope every ADMIN_OPS payload carries. */
export type AdminOpEnvelope = {
  op: AdminOpKind;
  /** Admin user id that requested the op (for the audit trail). */
  requestedBy: string;
  /** Free-text reason (required for every mutating op). */
  reason?: string;
  /**
   * Scheduler lock key. The worker serialises jobs by `serverId ?? type`;
   * an ADMIN_OPS job with no serverId would otherwise queue behind EVERY
   * other server-less ADMIN_OPS job. See adminOpsLockKey().
   */
  lockKey?: string;
  /** Written by the worker. */
  result?: unknown;
};

export type DiagnosePayload = AdminOpEnvelope & { op: "diagnose"; serverId: string };
export type GuestCmdPayload = AdminOpEnvelope & {
  op: "guest_cmd";
  serverId: string;
  command: string;
  params?: Record<string, string | number>;
};
export type IpReassignPayload = AdminOpEnvelope & {
  op: "ip_reassign";
  sourceServerId: string;
  targetServerId: string;
  /** The HOLD job placed on the target; released when this op ends. */
  holdJobId?: string;
};
export type HoldPayload = AdminOpEnvelope & { op: "hold" };
export type IpReleasePayload = AdminOpEnvelope & { op: "ip_release"; serverId: string };
export type IpAssignPayload = AdminOpEnvelope & {
  op: "ip_assign";
  serverId: string;
  /** Specific FREE pool address to hand out; omitted = first free in the node's pool. */
  address?: string;
  /** Bill the IP add-on at renewal (sets wantsDedicatedIp). */
  billable: boolean;
};
export type DriftScanPayload = AdminOpEnvelope & { op: "drift_scan" };
export type OrphanVmDestroyPayload = AdminOpEnvelope & { op: "orphan_vm_destroy"; nodeId: string; vmid: number };
export type OrphanIpReleasePayload = AdminOpEnvelope & { op: "orphan_ip_release"; ipId: string };
export type BulkPowerPayload = AdminOpEnvelope & {
  op: "bulk_power";
  action: "start" | "stop" | "reboot" | "game_restart" | "delete";
  serverIds: string[];
  concurrency: number;
  /** Persisted progress so a worker restart resumes instead of re-firing. */
  children?: { serverId: string; jobId: string | null; skipped?: string }[];
};

export type AdminOpPayload =
  | DiagnosePayload
  | GuestCmdPayload
  | IpReassignPayload
  | IpReleasePayload
  | IpAssignPayload
  | DriftScanPayload
  | OrphanVmDestroyPayload
  | OrphanIpReleasePayload
  | BulkPowerPayload
  | HoldPayload;

/**
 * The lock key the worker scheduler should use for an ADMIN_OPS job with no
 * serverId. Read-only ops get a per-job key (fully parallel, they mutate
 * nothing); fleet-wide singletons (drift scan) share one key so two scans
 * never overlap; everything else falls back to the payload's own key.
 *
 * Returns null for any job that isn't ADMIN_OPS so the worker keeps its
 * existing `type:<TYPE>` behaviour for every other job type.
 */
export function adminOpsLockKey(job: { id: string; type: string; serverId: string | null; payload: unknown }): string | null {
  if (job.type !== "ADMIN_OPS" || job.serverId) return null;
  const p = (job.payload ?? {}) as Partial<AdminOpEnvelope>;
  if (typeof p.lockKey === "string" && /^[a-z0-9:_-]{1,80}$/i.test(p.lockKey)) return `adminops:${p.lockKey}`;
  if (p.op && READ_ONLY_OPS.has(p.op as AdminOpKind) && p.op !== "drift_scan") return `adminops:job:${job.id}`;
  return `adminops:${String(p.op ?? "unknown")}`;
}

/** Bounds for free-text reasons recorded on mutating ops. */
export const REASON_MIN = 4;
export const REASON_MAX = 300;

export function cleanReason(raw: unknown): string | null {
  const s = String(raw ?? "")
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (s.length < REASON_MIN || s.length > REASON_MAX) return null;
  return s;
}

"use server";

/**
 * Admin Ops console — server actions. Every export is a network-reachable
 * endpoint, so every one of them:
 *   1. gates on requireArea(...) FIRST (fleet = ADMIN-only today; billing for
 *      money ops), and refuses while impersonating;
 *   2. validates every input (ids, reasons, typed confirmations) server-side —
 *      the UI's confirm dialog is a convenience, never the control;
 *   3. writes an AuditLog row with the admin, the target and the reason;
 *   4. hands anything remote to the worker as an ADMIN_OPS Job (the web
 *      process never mutates Proxmox/iptables), or reuses an existing,
 *      already-audited lifecycle action (serverAction, reconcile, gamePower,
 *      retryProvision, adjustBalance, refundPayment, adminExtendServer…)
 *      instead of re-implementing a money path.
 *
 * test/admin-ops-actions-guards.test.ts proves (1) structurally.
 */
import { revalidatePath } from "next/cache";
import type { Prisma } from "@prisma/client";
import { db } from "../db";
import { requireArea } from "../rbac";
import { assertNotImpersonating } from "../auth";
import { recordAudit } from "../audit";
import { withServerJobLock } from "../job-guard";
import { serverAction, reconcileServerFromProxmox, adminExtendServer, adminSetServerFree } from "../actions";
import { gamePower } from "../actions-game-control";
import { retryProvision } from "../actions-server-lifecycle";
import { adjustBalance, refundPayment } from "../actions-admin-billing";
import { setNodeAcceptsProvisions } from "../actions-nodes";
import { sendMail } from "../mailer";
import { emails } from "../email-templates";
import { buildGuestCommand } from "./guest-commands";
import { whyNot, serverStatusAfterAbort, type JobVerb } from "./job-queue";
import { planIpReassign, planIpRelease, planIpAssign, type IpOpServer, type IpPlan } from "./ip-ops";
import { planDrain, type DrainPlan } from "./drain-planner";
import { requestVmMove, type VmMoveResult } from "./vm-move";
import { BULK_ACTIONS, BULK_MAX_CONCURRENCY, BULK_MAX_SERVERS, type BulkAction } from "./bulk";
import { cleanReason, type AdminOpPayload } from "./types";
import type { FixKey } from "./diagnose-rules";

type Ok<T = object> = ({ ok: true } & T) | { ok: false; error: string };

const ID_RE = /^[a-z0-9]{8,40}$/i;
const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;

function badId(id: unknown): boolean {
  return typeof id !== "string" || !ID_RE.test(id);
}

async function gate(area: "fleet" | "billing" = "fleet") {
  const admin = await requireArea(area);
  await assertNotImpersonating();
  return admin;
}

async function enqueue(payload: AdminOpPayload, serverId: string | null = null, extra?: { status?: "RUNNING" }): Promise<string> {
  const job = await db.job.create({
    data: { type: "ADMIN_OPS", serverId, payload: payload as unknown as Prisma.InputJsonValue, ...(extra?.status ? { status: extra.status } : {}) },
    select: { id: true },
  });
  return job.id;
}

async function inflightCount(serverId: string): Promise<number> {
  return db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
}

function revalidateServer(id: string) {
  revalidatePath(`/admin/servers/${id}`);
  revalidatePath(`/admin/ops/servers/${id}`);
  revalidatePath(`/dashboard/servers/${id}`);
}

// ---------------------------------------------------------------------------
// Polling
// ---------------------------------------------------------------------------

export type OpJobView = {
  id: string;
  op: string | null;
  status: string;
  step: string | null;
  progress: number;
  error: string | null;
  result: unknown;
  createdAt: string;
  updatedAt: string;
};

/** Poll an ADMIN_OPS job. Returns null for any other job type. */
export async function getOpJob(jobId: string): Promise<OpJobView | null> {
  await gate();
  if (badId(jobId)) return null;
  const j = await db.job.findUnique({ where: { id: jobId } });
  if (!j || j.type !== "ADMIN_OPS") return null;
  const p = (j.payload ?? {}) as { op?: string; result?: unknown };
  return {
    id: j.id,
    op: p.op ?? null,
    status: j.status,
    step: j.step,
    progress: j.progress,
    error: j.error,
    result: p.result ?? null,
    createdAt: j.createdAt.toISOString(),
    updatedAt: j.updatedAt.toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Diagnose + fixes
// ---------------------------------------------------------------------------

export async function startDiagnose(serverId: string): Promise<Ok<{ jobId: string }>> {
  "clear_stuck_job",
  "open_guest_logs",
];

/** Apply a one-click fix suggested by Diagnose — always via the existing path. */
export async function applyFix(serverId: string, fix: string): Promise<Ok<{ message: string; jobId?: string; navigate?: string }>> {
  const admin = await gate();
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  if (!FIXES.includes(fix as FixKey)) return { ok: false, error: "Unknown fix." };
  const server = await db.server.findUnique({ where: { id: serverId }, select: { id: true, hostname: true, subdomain: true } });
  if (!server) return { ok: false, error: "Server not found." };
  const done = async (message: string, jobId?: string) => {
    await recordAudit(admin.id, "adminops.fix", `${server.hostname} ${fix}${jobId ? ` job=${jobId}` : ""}`);
    revalidateServer(serverId);
    return { ok: true as const, message, jobId };
  };
  switch (fix as FixKey) {
    case "start_vm":
    case "reboot_vm": {
      const r = await serverAction(serverId, fix === "start_vm" ? "start" : "reboot");
      if (r && "error" in r && r.error) return { ok: false, error: r.error };
      return done(fix === "start_vm" ? "START queued." : "REBOOT queued.", r && "jobId" in r ? r.jobId : undefined);
    }
    case "reconcile_status": {
      const r = await reconcileServerFromProxmox(serverId);
      if (r.error) return { ok: false, error: r.error };
      return done(r.status ? `Status reconciled → ${r.status}.` : r.message ?? "Nothing to change.");
    }
    case "restart_game_service": {
      const r = await gamePower(serverId, "restart");
      if (!r.ok) return { ok: false, error: r.error };
      return done("Game service restart queued.", r.jobId);
    }
    case "sync_forwards": {
      const pending = await db.job.findFirst({ where: { type: "SYNC_FORWARDS", status: "QUEUED" }, select: { id: true } });
      const id = pending?.id ?? (await db.job.create({ data: { type: "SYNC_FORWARDS" }, select: { id: true } })).id;
      return done("NAT re-sync queued (all nodes, diff-only — no flush).", id);
    }
    case "sync_game_dns": {
      if (!server.subdomain) return { ok: false, error: "This server has no managed subdomain." };
      const j = await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId }, select: { id: true } });
      return done("Subdomain DNS re-sync queued.", j.id);
    }
    case "retry_provision": {
      const r = await retryProvision(serverId);
