      return { ok: true, message: "Opening the job queue.", navigate: `/admin/ops/jobs?server=${serverId}` };
    case "open_guest_logs":
      return { ok: true, message: "Open Guest tools below.", navigate: `/admin/ops/servers/${serverId}#guest` };
