/**
 * Reassign a dedicated IP between two servers on the same node. `confirm` must
 * be the IP address itself. The job is pinned to the SOURCE server (so the
 * scheduler serialises it against that server's jobs) and a HOLD row is
 * placed on the TARGET so customer/admin power actions there are refused
 * ("another operation running") until the move finishes.
 */
export async function startIpReassign(sourceServerId: string, targetServerId: string, reason: string, confirm: string): Promise<Ok<{ jobId: string }>> {
  const admin = await gate();
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters) — it goes in the audit log." };
  const plan = await previewIpReassign(sourceServerId, targetServerId);
  if (!plan.ok) return plan;
  const src = await db.server.findUnique({ where: { id: sourceServerId }, include: { dedicatedIp: true } });
  if (!src?.dedicatedIp || confirm.trim() !== src.dedicatedIp.address) return { ok: false, error: `Type the IP address (${src?.dedicatedIp?.address ?? "?"}) to confirm.` };
  const out = await withServerJobLock(targetServerId, async (tx) => {
    const busy = await tx.job.count({ where: { serverId: { in: [sourceServerId, targetServerId] }, status: { in: ["QUEUED", "RUNNING"] } } });
    if (busy) return null;
    const hold = await tx.job.create({
      data: { type: "ADMIN_OPS", serverId: targetServerId, status: "RUNNING", step: "Held for an IP reassign", payload: { op: "hold", requestedBy: admin.id } as Prisma.InputJsonValue },
      select: { id: true },
    });
    const job = await tx.job.create({
      data: {
        type: "ADMIN_OPS",
        serverId: sourceServerId,
        payload: { op: "ip_reassign", requestedBy: admin.id, reason: why, sourceServerId, targetServerId, holdJobId: hold.id } as Prisma.InputJsonValue,
      },
      select: { id: true },
    });
    return job.id;
  });
  if (!out) return { ok: false, error: "One of the servers just picked up another job — try again when it's idle." };
  await recordAudit(admin.id, "adminops.ip_reassign.request", `${src.dedicatedIp.address} ${src.hostname} -> ${targetServerId} reason="${why}"`);
  revalidateServer(sourceServerId);
  revalidateServer(targetServerId);
  return { ok: true, jobId: out };
}


export async function jobIntervene(jobId: string, verb: string, reason: string): Promise<Ok<{ message: string }>> {
  const admin = await gate();
  if (badId(jobId)) return { ok: false, error: "Invalid job." };
  if (!["requeue", "cancel", "force_fail"].includes(verb)) return { ok: false, error: "Unknown action." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  const j = await db.job.findUnique({ where: { id: jobId }, include: { server: { select: { id: true, hostname: true, status: true } } } });
  if (!j) return { ok: false, error: "Job not found." };
  const refused = whyNot(verb as JobVerb, j);
  if (refused) return { ok: false, error: refused };
  // Compare-and-swap on the status we validated, so a job that moved on in the
  // meantime is never clobbered.
  const stamp = `[${verb} by admin ${new Date().toISOString().slice(0, 16)}Z: ${why}]`;
  if (verb === "requeue") {
    const r = await db.job.updateMany({ where: { id: j.id, status: "FAILED" }, data: { status: "QUEUED", attempts: 0, error: `${stamp} previous: ${(j.error ?? "").slice(0, 400)}`, progress: 0, step: null } });
    if (r.count !== 1) return { ok: false, error: "The job changed state — refresh." };
  } else {
    const from = verb === "cancel" ? "QUEUED" : "RUNNING";
    const r = await db.job.updateMany({ where: { id: j.id, status: from }, data: { status: "FAILED", attempts: 99, error: `${stamp}${j.error ? ` previous: ${j.error.slice(0, 400)}` : ""}` } });
    if (r.count !== 1) return { ok: false, error: "The job changed state — refresh." };
    if (j.server) {
      const after = serverStatusAfterAbort(j.type, j.server.status);
      if (after) await db.server.update({ where: { id: j.server.id }, data: { status: after.status, provisionError: after.note } });
    }
  }
  await recordAudit(admin.id, `adminops.job.${verb}`, `${j.type} ${j.id}${j.server ? ` ${j.server.hostname}` : ""} reason="${why}"`);
  revalidatePath("/admin/ops/jobs");
  revalidatePath("/admin/jobs");
  if (j.server) revalidateServer(j.server.id);
  return { ok: true, message: verb === "requeue" ? "Re-queued." : verb === "cancel" ? "Cancelled." : "Marked failed." };
}

