import { useCallback, useEffect, useRef, useState } from "react";
import { getOpJob, type OpJobView } from "@/lib/admin-ops/actions";

/**
 * Poll one ADMIN_OPS job until it is DONE/FAILED. `jobId` null = idle.
 * Backs off from 1.5s to 4s so a long op (bulk, drift) doesn't hammer the DB.
 */
export function useOpJob(jobId: string | null, initial: OpJobView | null = null) {
  const [job, setJob] = useState<OpJobView | null>(initial);
  const tries = useRef(0);
  useEffect(() => {
    if (!jobId) return;
    let alive = true;
    tries.current = 0;
    const tick = async () => {
      const j = await getOpJob(jobId).catch(() => null);
      if (!alive) return;
      if (j) setJob(j);
      if (!j || (j.status !== "DONE" && j.status !== "FAILED")) {
        tries.current++;
        setTimeout(tick, Math.min(4000, 1500 + tries.current * 250));
      }
    };
    tick();
    return () => {
      alive = false;
    };
  }, [jobId]);
  const busy = !!jobId && (!job || job.id !== jobId || job.status === "QUEUED" || job.status === "RUNNING");
  return { job, busy };
}

export function useAction<A extends unknown[], R>(fn: (...a: A) => Promise<R>) {
  const [pending, setPending] = useState(false);
  const run = useCallback(
    async (...a: A): Promise<R | null> => {
      setPending(true);
      try {
        return await fn(...a);
      } catch (e) {
        return { ok: false, error: String((e as Error)?.message ?? e) } as unknown as R;
      } finally {
        setPending(false);
      }
    },
    [fn],
  );
  return { run, pending };
}

export function JobProgress({ job, busy }: { job: OpJobView | null; busy: boolean }) {
  if (!job) return null;
