      <div className="flex items-center justify-between text-xs text-slate-400">
        <span>{busy ? job.step ?? (job.status === "QUEUED" ? "Queued — waiting for a worker slot…" : "Working…") : failed ? "Failed" : "Finished"}</span>
        <span className="font-mono">{job.status.toLowerCase()}</span>
      </div>
      {busy && (
        <div className="h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
          <div className="h-full rounded-full bg-gradient-to-r from-[#3b6be8] to-[#7b3fef] transition-all" style={{ width: `${Math.max(6, job.progress)}%` }} />
        </div>
      )}
      {failed && <p className="text-xs text-red-400">{(job.result as { error?: string } | null)?.error ?? job.error ?? "The operation failed."}</p>}
    </div>
  );
}

