import Link from "next/link";
import { usePathname } from "next/navigation";
import { hrefMatches, navItemForPath } from "@/lib/admin-nav";

export type SubTabItem = { label: string; href: string };

/**
 * Horizontal tab bar for one admin nav item's children (lib/admin-nav.ts).
 * Underline style, scrolls horizontally on narrow screens instead of
 * wrapping. Renders nothing for a single-member item.
 */
export function SubTabs({
  items,
  badges,
}: {
  items: SubTabItem[];
  /** Per-route attention counts, keyed by href. Shown as a pill on the tab. */
  badges?: Record<string, number>;
}) {
  const pathname = usePathname() ?? "";
  if (items.length < 2) return null;
  // Longest match wins so /admin/coldemail doesn't light up on /admin/coldemail/inbox.
  const activeHref = items
    .filter((i) => hrefMatches(i.href, pathname))
    .sort((a, b) => b.href.length - a.href.length)[0]?.href;

  return (
    <nav className="adm-subtabs" aria-label="Section">
      {items.map((item) => {
        const count = badges?.[item.href] ?? 0;
        return (
          <Link
            key={item.href}
            href={item.href}
            className="adm-subtab"
            aria-current={item.href === activeHref ? "page" : undefined}
          >
            {item.label}
            {count > 0 && <span className="adm-count" style={{ marginLeft: 0 }}>{count > 99 ? "99+" : count}</span>}
          </Link>
        );
      })}
    </nav>
  );
}

/**
 * Auto-resolving tab bar, mounted once by app/admin/layout.tsx: finds the nav
 * item owning the current path and renders its children. `allowed` (from the
 * layout's RBAC filter) hides tabs the role can't open.
 */
export function AdminSubTabs({
  badges,
  allowed,
}: {
  badges?: Record<string, number>;
  allowed?: string[];
}) {
  const pathname = usePathname() ?? "";
  const hit = navItemForPath(pathname);
  if (!hit?.item.children) return null;
  const items = hit.item.children
    .filter((c) => !c.pending)
    .filter((c) => !allowed || allowed.includes(c.href))
    .map((c) => ({ label: c.label, href: c.href }));
  return <SubTabs items={items} badges={badges} />;
}
