export function Meter({ pct, warnAt = 80, alertAt = 90, label }: { pct: number; warnAt?: number; alertAt?: number; label?: string }) {
  const p = Math.max(0, Math.min(100, pct));
  return (
    <div
      className="adm-meter"
      data-tone={p >= alertAt ? "alert" : p >= warnAt ? "warn" : undefined}
      role="meter"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(p)}
      aria-label={label}
    >
      <span style={{ width: `${p}%` }} />
    </div>
  );
}

